215	.ows{display:flex;gap:12px;align-items:center}
216	.ows span{display:inline-flex;align-items:center;gap:6px;font-size:12.5px;font-weight:600;color:var(--ink2);font-variant-numeric:tabular-nums}
217	.tm-chips{display:none;flex-wrap:wrap;gap:8px;margin-top:14px}
