// Snapshot the doc-audit team map for every board: DOM, hover states, screenshots.
// usage: node audit-snap.js <port> <outdir>
const { chromium } = require("D:/Atharva/video-studio/node_modules/playwright");
const fs = require("fs"), path = require("path");
const port = process.argv[2], out = process.argv[3];
fs.mkdirSync(out, { recursive: true });
const ids = JSON.parse(fs.readFileSync(path.join(__dirname, "base-docs/audits/index.json"), "utf8")).audits.map(a => a.id);
(async () => {
  const b = await chromium.launch();
  const res = {};
  for (const w of [1440, 900, 375]) {
    const ctx = await b.newContext({ viewport: { width: w, height: 1000 }, reducedMotion: "reduce" });
    await ctx.route(/avatars\.githubusercontent\.com|github\.com\/.*\.png/, r => r.abort());
    const pg = await ctx.newPage();
    const errs = [];
    pg.on("pageerror", e => errs.push(String(e)));
    pg.on("console", m => { if (m.type() === "error" || m.type() === "warning") errs.push(m.text()) });
    for (const id of ids) {
      await pg.goto(`http://127.0.0.1:${port}/doc-audit/?id=${id}`, { waitUntil: "networkidle" });
      await pg.waitForTimeout(300);
      const r = {};
      r.html = await pg.evaluate(() => { const t = document.getElementById("r-team"); return t ? t.outerHTML : "" });
      r.next = await pg.evaluate(() => document.getElementById("r-nx").outerHTML);
      // hover the first person and first area, record the sentence and lit nodes
      const hov = async sel => {
        const h = await pg.$(sel); if (!h || !(await h.isVisible())) return null;
        await h.hover(); await pg.waitForTimeout(50);
        const v = await pg.evaluate(() => ({ say: document.getElementById("tm-say").textContent, hi: document.querySelectorAll("#tm .hi").length, nx: document.querySelectorAll("#r-nx>li.lit").length }));
        await pg.mouse.move(2, 2); return v;
      };
      r.hp = await hov(".tm-p"); r.ha = await hov(".tm-a"); r.har = await hov(".ar");
      r.say = await pg.evaluate(() => document.getElementById("tm-say").textContent);
      res[w + ":" + id] = r;
      const t = await pg.$("#r-team");
      if (t && await t.isVisible()) await t.screenshot({ path: path.join(out, `${w}-${id}.png`) });
    }
    res[w + ":errors"] = errs;
    await ctx.close();
  }
  fs.writeFileSync(path.join(out, "dom.json"), JSON.stringify(res, null, 1));
  await b.close();
  console.log("ok", Object.keys(res).length);
})();

