.board img{display:block;width:100%;height:auto;border-radius:10px}

/* Doc-audit team map: a deeper indigo world under the Doc-audit band. People on the left, parts of the
   code on the right, a ribbon per pair. assets/team-map.js draws it from a real board, loaded on approach. */
.b-team{--tint:oklch(94.6% .032 284);--glow:oklch(90% .07 282/.75);--dot:oklch(46% .2 283/.15);--edge:oklch(87.5% .05 284);--c:oklch(48% .2 283);--cd:oklch(40% .17 283);--link:oklch(40% .17 283)}
#team{--line2:oklch(94.6% .005 255);--faint:oklch(60% .01 255);--po:oklch(70% .01 255);
 --p0:oklch(62% .15 295);--p1:oklch(62% .15 256);--p2:oklch(62% .15 195);--p3:oklch(62% .15 150);--p4:oklch(62% .15 78);--p5:oklch(62% .15 35);
