// Screenshot the homepage team section at several widths, with hover states.
// usage: node home-snap.js <port> <outdir> [widths]
const { chromium } = require("D:/Atharva/video-studio/node_modules/playwright");
const fs = require("fs"), path = require("path");
const port = process.argv[2], out = process.argv[3];
const widths = (process.argv[4] || "1440,1024,768,375").split(",").map(Number);
fs.mkdirSync(out, { recursive: true });
(async () => {
  const b = await chromium.launch({ channel: "msedge" });
  const log = {};
  for (const w of widths) {
    const ctx = await b.newContext({ viewport: { width: w, height: 900 }, deviceScaleFactor: 1 });
    const pg = await ctx.newPage();
    const errs = [];
    pg.on("pageerror", e => errs.push("pageerror " + e));
    pg.on("console", m => { if (m.type() === "error" || m.type() === "warning") errs.push(m.type() + " " + m.text() + " " + JSON.stringify(m.location())) });
    await pg.goto(`http://127.0.0.1:${port}/`, { waitUntil: "load" });
    await pg.evaluate(() => document.getElementById("team").scrollIntoView({ block: "start" }));
    await pg.waitForTimeout(3200);
    const sec = await pg.$("#team");
    await sec.screenshot({ path: path.join(out, `team-${w}.png`) });
    const info = await pg.evaluate(() => ({
      sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth,
      say: document.getElementById("tmh-say").textContent,
      h: Math.round(document.getElementById("team").getBoundingClientRect().height),
      tmh: Math.round(document.getElementById("tmh").getBoundingClientRect().height),
    }));
    // hover a person, an area and a task
    const shots = [["person", ".tmh-p:nth-child(2)"], ["area", ".tmh-a:nth-child(2)"], ["task", "#tmh-nx li:nth-child(2)"], ["arealist", ".tmh-ar"]];
    for (const [n, sel] of shots) {
      const h = await pg.$(sel);
      if (!h || !(await h.isVisible())) continue;
      await h.hover(); await pg.waitForTimeout(400);
      info["say_" + n] = await pg.evaluate(() => document.getElementById("tmh-say").textContent);
      await sec.screenshot({ path: path.join(out, `team-${w}-hover-${n}.png`) });
      await pg.mouse.move(1, 1);
    }
    info.errs = errs;
    log[w] = info;
    await ctx.close();
  }
  fs.writeFileSync(path.join(out, "log.json"), JSON.stringify(log, null, 1));
  console.log(JSON.stringify(log, null, 1));
  await b.close();
})();

