// Render the live team map once and save it as the no-JS still.
const { chromium } = require("D:/Atharva/video-studio/node_modules/playwright");
(async () => {
  const b = await chromium.launch({ channel: "msedge" });
  const pg = await b.newPage({ viewport: { width: 1440, height: 1800 }, deviceScaleFactor: 1.5, reducedMotion: "reduce" });
  await pg.goto("http://127.0.0.1:" + process.argv[2] + "/", { waitUntil: "load" });
  await pg.evaluate(() => document.getElementById("team").scrollIntoView({ block: "start" }));
  await pg.waitForTimeout(1500);
  await pg.waitForLoadState("networkidle");
  await pg.waitForFunction(() => [...document.querySelectorAll("#tmh img")].every(i => i.complete));
  await pg.waitForTimeout(500);
  const el = await pg.$("#tmh");
  console.log(JSON.stringify(await el.boundingBox()));
  await el.screenshot({ path: process.argv[3] });
  await b.close();
})();

